script:
frappe.ui.form.on('Booking Kamar', {
    kamar: function(frm) {
        if (frm.doc.kamar) {
            frappe.db.get_value('Kamar', frm.doc.kamar, 'harga_sewa', function(r) {
                if (r && frm.doc.durasi_bulan) {
                    frm.set_value('total_harga', r.harga_sewa * frm.doc.durasi_bulan);
                }
            });
        }
    },
    durasi_bulan: function(frm) {
        if (frm.doc.kamar) {
            frappe.db.get_value('Kamar', frm.doc.kamar, 'harga_sewa', function(r) {
                if (r) {
                    frm.set_value('total_harga', r.harga_sewa * frm.doc.durasi_bulan);
                }
            });
        }
    }
});
